window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-045f3ef62620a0d4"]={"versions": [{"id": "FIG-045f3ef62620a0d4", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Protokolldiagramm / Paket-Layout-Diagramm. Das Schaubild stellt das Byte-Layout des Dlt Standard Headers gemäß AUTOSAR PRS LogAndTraceProtocol dar und definiert die serielle Bytereihenfolge sowie die Feldaufteilung innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Layout definiert folgende Felder, ihre Kurznamen (Short Name) und Byte-Positionen:</p>\n<ul class=\"fig-list\"><li><strong>Header Type</strong> (<code>HTYP</code>): Byte 0 (obligatorisch, farblich hervorgehoben).\n</li><li><strong>Message Counter</strong> (<code>MCNT</code>): Byte 1 (obligatorisch).\n</li><li><strong>Length</strong> (<code>LEN</code>): Byte 2–3 (obligatorisch, 16 Bit).\n</li><li><strong>ECU ID</strong> (<code>ECU</code>): Byte 4–7 (optional, 32 Bit / 4 Bytes).\n</li><li><strong>Session ID</strong> (<code>SEID</code>): Byte 8–11 (optional, 32 Bit / 4 Bytes).\n</li><li><strong>Timestamp</strong> (<code>TMSP</code>): Byte 12–15 (optional, 32 Bit / 4 Bytes).\n</li></ul>\n<p class=\"fig-p\">Insgesamt umfasst der Standard Header bei voller Bestückung aller optionalen Felder eine Gesamtlänge von 16 Bytes (Byte 0 bis Byte 15).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Feldausrichtung und Serialisierungsreihenfolge von links nach rechts (Byte 0 aufsteigend bis maximal Byte 15). Die Felder <code>HTYP</code>, <code>MCNT</code> und <code>LEN</code> bilden den minimalen Standard-Header (4 Bytes). Das Vorhandensein der optionalen Felder <code>ECU</code>, <code>SEID</code> und <code>TMSP</code> wird über entsprechende Steuerbits im <code>HTYP</code>-Feld gesteuert und schlägt sich in der Gesamtlänge <code>LEN</code> der Nachricht nieder.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Dlt Standard Headers gemäß <code>[PRS_Dlt_00458]</code>. Protokollparser und Dlt-Dienste müssen die Felder zwingend in der dargestellten Reihenfolge dekodieren und encodieren. Für optionale Felder ist die Auswertung der Bitmasken in <code>HTYP</code> bindend, um die tatsächlichen Byte-Offsets nachfolgender Felder sowie der Payload korrekt zu bestimmen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a8726ab17d2fd5a5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Protokolldiagramm / Paket-Layout-Diagramm. Das Schaubild stellt das Byte-Layout des Dlt Standard Headers gemäß AUTOSAR PRS LogAndTraceProtocol dar und definiert die serielle Bytereihenfolge sowie die Feldaufteilung innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Layout definiert folgende Felder, ihre Kurznamen (Short Name) und Byte-Positionen:</p>\n<ul class=\"fig-list\"><li><strong>Header Type</strong> (<code>HTYP</code>): Byte 0 (obligatorisch, farblich hervorgehoben).\n</li><li><strong>Message Counter</strong> (<code>MCNT</code>): Byte 1 (obligatorisch).\n</li><li><strong>Length</strong> (<code>LEN</code>): Byte 2–3 (obligatorisch, 16 Bit).\n</li><li><strong>ECU ID</strong> (<code>ECU</code>): Byte 4–7 (optional, 32 Bit / 4 Bytes).\n</li><li><strong>Session ID</strong> (<code>SEID</code>): Byte 8–11 (optional, 32 Bit / 4 Bytes).\n</li><li><strong>Timestamp</strong> (<code>TMSP</code>): Byte 12–15 (optional, 32 Bit / 4 Bytes).\n</li></ul>\n<p class=\"fig-p\">Insgesamt umfasst der Standard Header bei voller Bestückung aller optionalen Felder eine Gesamtlänge von 16 Bytes (Byte 0 bis Byte 15).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Feldausrichtung und Serialisierungsreihenfolge von links nach rechts (Byte 0 aufsteigend bis maximal Byte 15). Die Felder <code>HTYP</code>, <code>MCNT</code> und <code>LEN</code> bilden den minimalen Standard-Header (4 Bytes). Das Vorhandensein der optionalen Felder <code>ECU</code>, <code>SEID</code> und <code>TMSP</code> wird über entsprechende Steuerbits im <code>HTYP</code>-Feld gesteuert und schlägt sich in der Gesamtlänge <code>LEN</code> der Nachricht nieder.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Dlt Standard Headers gemäß <code>[PRS_Dlt_00458]</code>. Protokollparser und Dlt-Dienste müssen die Felder zwingend in der dargestellten Reihenfolge dekodieren und encodieren. Für optionale Felder ist die Auswertung der Bitmasken in <code>HTYP</code> bindend, um die tatsächlichen Byte-Offsets nachfolgender Felder sowie der Payload korrekt zu bestimmen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-045f3ef62620a0d4", "to": "FIG-a8726ab17d2fd5a5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
